        String clean1 = s1.replaceAll("[^a-zA-Z]", "").toLowerCase();
        String clean2 = s2.replaceAll("[^a-zA-Z]", "").toLowerCase();

        // If lengths differ → not anagram
        if (clean1.length() != clean2.length()) {
            return false;
