            count[c - 'a']--;
        }

        // Check if all counts are zero
        for (int num : count) {
            if (num != 0) {
                return false;
            }
        }

        return true;
    }

    public static void main(String[] args) {
        String str1 = "Listen!";
        String str2 = "Silent";

        System.out.println(isAnagram(str1, str2)); // true
